package com.sanctuarygames.createtransit.elevator.model;
import com.sanctuarygames.createtransit.elevator.*;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
public final class ModelLandingBlock extends ElevatorPartBlock {
 public static final IntegerProperty SIZE=IntegerProperty.create("size",2,5),COLUMN=IntegerProperty.create("column",0,4),ROW=IntegerProperty.create("row",0,2);
 public static final BooleanProperty KIT3=BooleanProperty.create("kit3"),OPEN=BooleanProperty.create("open"),GLASS=BooleanProperty.create("glass");
 public ModelLandingBlock(Properties p){super(p,Kind.LANDING_DOOR);registerDefaultState(defaultBlockState().setValue(KIT3,true).setValue(SIZE,3).setValue(COLUMN,0).setValue(ROW,0).setValue(OPEN,false).setValue(GLASS,false));}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(SIZE,COLUMN,ROW,OPEN,GLASS,KIT3);}
 public static BlockPos part(BlockPos base,Direction back,int col,int row){return base.relative(back.getClockWise().getOpposite(),col).above(row);}
 public static BlockPos base(BlockPos p,BlockState s){return part(p,s.getValue(FACING),-s.getValue(COLUMN),-s.getValue(ROW));}
 public static boolean complete(Level l,BlockPos base,int size,Direction facing){for(int x=0;x<size;x++)for(int y=0;y<(l.getBlockState(base).hasProperty(KIT3)&&l.getBlockState(base).getValue(KIT3)?3:2);y++){var p=part(base,facing,x,y);if(!l.hasChunkAt(p))return false;var s=l.getBlockState(p);if(!(s.getBlock() instanceof ModelLandingBlock)||s.getValue(SIZE)!=size||s.getValue(COLUMN)!=x||s.getValue(ROW)!=y||s.getValue(FACING)!=facing)return false;}return true;}
 public static boolean available(Level l,BlockPos base,int size,Direction facing){return available(l,base,size,facing,size>=3);}
 public static boolean available(Level l,BlockPos base,int size,Direction facing,boolean kit3){kit3=size>=3;for(int x=0;x<size;x++)for(int y=0;y<(kit3?3:2);y++){var p=part(base,facing,x,y);if(!l.hasChunkAt(p)||!l.getBlockState(p).canBeReplaced()&&!(l.getBlockState(p).getBlock() instanceof ModelLandingBlock))return false;}return true;}
 public static void install(Level l,BlockPos base,int size,Direction facing,boolean glass,int primary,int accent){install(l,base,size,facing,glass,primary,accent,size>=3);}
 public static void install(Level l,BlockPos base,int size,Direction facing,boolean glass,int primary,int accent,boolean kit3){kit3=size>=3;for(int x=0;x<size;x++)for(int y=0;y<(kit3?3:2);y++){var p=part(base,facing,x,y);l.setBlock(p,ElevatorRegistry.MODEL_LANDING.get().defaultBlockState().setValue(KIT3,kit3).setValue(SIZE,size).setValue(COLUMN,x).setValue(ROW,y).setValue(FACING,facing).setValue(GLASS,glass),Block.UPDATE_ALL);if(l.getBlockEntity(p) instanceof ElevatorPartEntity be)be.setColors(primary,accent);}}
 public static void open(Level l,BlockPos base,boolean open){var state=l.getBlockState(base);if(!(state.getBlock() instanceof ModelLandingBlock))return;for(int x=0;x<state.getValue(SIZE);x++)for(int y=0;y<(state.getValue(KIT3)?3:2);y++){var p=part(base,state.getValue(FACING),x,y);var s=l.getBlockState(p);if(s.getBlock() instanceof ModelLandingBlock&&s.getValue(OPEN)!=open)l.setBlock(p,s.setValue(OPEN,open),Block.UPDATE_CLIENTS);}}
 public static CabinConfiguration configuration(BlockState s,ElevatorPartEntity be){if(be instanceof ModelLandingEntity cached&&cached.getLevel()!=null&&cached.getLevel().isClientSide&&cached.renderState==s&&cached.renderConfiguration!=null)return cached.renderConfiguration;var c=CabinConfiguration.defaults(s.getValue(SIZE),CabinConfiguration.Variant.SOLID);var p=c.save();p.setProperty("kit3",Boolean.toString(s.getValue(KIT3)&&s.getValue(SIZE)>=3));p.setProperty("front",s.getValue(GLASS)?"GLASS":"SOLID");if(be!=null){p.setProperty("primary",""+be.paint());p.setProperty("secondary",""+be.accent());}if(be instanceof ModelLandingEntity e){p.setProperty("skin",e.skin.name());p.setProperty("ledColor",""+e.ledColor);p.setProperty("sideIndicatorStyle",e.sideIndicatorStyle.name());p.setProperty("indicatorStyle",e.indicatorStyle.name());p.setProperty("frameType",e.frameType.name());p.setProperty("mechanism",e.mechanism.name());p.setProperty("twoSpeed",Boolean.toString(e.twoSpeed));p.setProperty("indicators",Boolean.toString(e.indicators));boolean glass=s.getValue(GLASS);
  var style=e.style;
  if(style==CabinConfiguration.DoorStyle.GLASS||style==CabinConfiguration.DoorStyle.SOLID)
   style=glass?CabinConfiguration.DoorStyle.GLASS:CabinConfiguration.DoorStyle.SOLID;
  p.setProperty("doorStyle",style.name());p.setProperty("wood",e.woodMaterial);p.setProperty("glazing",glass?(e.glazing==CabinConfiguration.Glazing.SLIM_GLASS?"SLIM_GLASS":"FULL_GLASS"):"SOLID");p.setProperty("materialPrimary",e.primaryMaterial);p.setProperty("materialSecondary",e.secondaryMaterial);}var result=CabinConfiguration.load(p);if(be instanceof ModelLandingEntity cached&&cached.getLevel()!=null&&cached.getLevel().isClientSide){cached.renderState=s;cached.renderConfiguration=result;}return result;}
 @Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){super.onRemove(s,l,p,next,moving);if(!l.isClientSide&&!s.is(next.getBlock())){var base=base(p,s);for(int x=0;x<s.getValue(SIZE);x++)for(int y=0;y<3;y++){var cell=part(base,s.getValue(FACING),x,y);if(!cell.equals(p)&&l.getBlockState(cell).getBlock() instanceof ModelLandingBlock)l.removeBlock(cell,false);}}}
 @Override protected RenderShape getRenderShape(BlockState s){return RenderShape.ENTITYBLOCK_ANIMATED;}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new ModelLandingEntity(p,s);}
 @Override public <T extends BlockEntity>BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T>type){return createTickerHelper(type,ElevatorRegistry.MODEL_LANDING_ENTITY.get(),ModelLandingEntity::tick);}
 @Override protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext ctx){var be=l.getBlockEntity(p);double progress=be instanceof ModelLandingEntity e?e.linearProgress(1):s.getValue(OPEN)?1:0;var result=Shapes.empty();int col=s.getValue(COLUMN),row=s.getValue(ROW);for(var b:CabinGeometry.landingCollision(configuration(s,be instanceof ElevatorPartEntity e?e:null),progress)){double x=col==0?b.x0():Math.max(col,b.x0()),X=col==s.getValue(SIZE)-1?b.x1():Math.min(col+1,b.x1()),y=Math.max(row,b.y0()),Y=Math.min(row+1,b.y1());if(X>x&&Y>y)result=Shapes.or(result,Shapes.box(x-col,y-row,b.z0(),X-col,Y-row,b.z1()));}return turn(result,s.getValue(FACING).getOpposite());}
 @Override protected ItemInteractionResult useItemOn(net.minecraft.world.item.ItemStack stack,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){
  if(level.getBlockEntity(base(pos,state)) instanceof ModelLandingEntity door){
   if(stack.getItem() instanceof ModelLandingItem){if(!level.isClientSide){if(door.markerDrive()!=null&&level.getBlockEntity(door.markerDrive()) instanceof ElevatorDriveEntity owner)owner.openPanel(player,true,base(pos,state));else ElevatorFeedback.error(player,com.sanctuarygames.createtransit.TransitText.key("message.createtransit.elevator.link_this_landing_to_its_elevator"));}return ItemInteractionResult.sidedSuccess(level.isClientSide);}
   if(ElevatorLinking.wrench(stack)){if(!level.isClientSide&&player.mayBuild()&&level.mayInteract(player,pos)){if(player.isShiftKeyDown())door.cycleStyle();else door.link(player);}return ItemInteractionResult.sidedSuccess(level.isClientSide);}
   if(door.style==CabinConfiguration.DoorStyle.COPYCAT&&stack.getItem() instanceof net.minecraft.world.item.BlockItem block){if(!level.isClientSide&&player.mayBuild())door.material(block.getBlock(),player.isShiftKeyDown());return ItemInteractionResult.sidedSuccess(level.isClientSide);}
  }
  if(!(stack.getItem() instanceof net.minecraft.world.item.DyeItem dye))return super.useItemOn(stack,state,level,pos,player,hand,hit);
  if(!player.mayBuild())return ItemInteractionResult.FAIL;if(level.isClientSide)return ItemInteractionResult.SUCCESS;
  var base=base(pos,state);var origin=level.getBlockState(base);if(!(level.getBlockEntity(base) instanceof ModelLandingEntity be))return ItemInteractionResult.FAIL;
  int primary=player.isShiftKeyDown()?be.paint():dye.getDyeColor().getId(),secondary=player.isShiftKeyDown()?dye.getDyeColor().getId():be.accent();boolean changed=primary!=be.paint()||secondary!=be.accent();
  for(int x=0;x<state.getValue(SIZE);x++)for(int row=0;row<(state.getValue(KIT3)?3:2);row++){var p=part(base,state.getValue(FACING),x,row);if(level.getBlockEntity(p) instanceof ModelLandingEntity member)member.setColors(primary,secondary);}if(changed&&!player.isCreative())stack.shrink(1);return ItemInteractionResult.SUCCESS;
 }
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){if(!l.isClientSide){var base=base(p,s);if(player.isShiftKeyDown()&&l.getBlockEntity(base) instanceof ModelLandingEntity e){if(e.markerDrive()!=null&&l.getBlockEntity(e.markerDrive()) instanceof ElevatorDriveEntity owner){owner.openPanel(player,true,base);return InteractionResult.SUCCESS;}if(player.mayBuild()&&l.mayInteract(player,base))e.cycleGlazing();return InteractionResult.SUCCESS;}ElevatorDriveEntity d=null;if(l.getBlockEntity(base) instanceof ModelLandingEntity be&&be.markerDrive()!=null&&l.hasChunkAt(be.markerDrive())&&l.getBlockEntity(be.markerDrive()) instanceof ElevatorDriveEntity linked)d=linked;else d=ElevatorNetwork.forCall(l,base);if(d!=null)d.requestFloor(base.getY()-1);}return InteractionResult.sidedSuccess(l.isClientSide);}
}
